    /**
     * Render an inline SVG for the given icon name. Accepts both the plain key
     * (`users`) and the Filament style (`heroicon-o-users`).
     */
    public static function render(?string $name, string $class = 'h-5 w-5'): string
    {
        $key = self::key($name);
        $path = self::PATHS[$key] ?? self::PATHS['gauge'];

        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="%s" aria-hidden="true">%s</svg>',
            $class,
            $path,
        );
    }

    /**
     * All available icon names, useful to populate the icon picker.
     *
     * @return array<int, string>
     */
    public static function keys(): array
    {
        return array_keys(self::PATHS);
    }

    /**
     * All icons keyed by their plain name, so the icon picker can swap the
     * preview client side without a round trip.
     *
     * @return array<string, string>
     */
    public static function map(string $class = 'h-6 w-6'): array
    {
        $map = [];

        foreach (array_keys(self::PATHS) as $key) {
            $map[$key] = self::render($key, $class);
        }

        return $map;
    }

    /**
     * Reduce any stored value (`heroicon-o-users`, `users`) to the plain key
     * used by the picker. Returns null when there is nothing to show.
     */
    public static function normalize(?string $name): ?string
    {
        return filled($name) ? self::key($name) : null;
    }

    protected static function key(?string $name): string
    {
        $name = (string) $name;

        return Str::of($name)
            ->replaceStart('heroicon-o-', '')
            ->replaceStart('heroicon-', '')
            ->toString();
    }
}
